import './App.css';
import cafeImg from './imagenes/Deus_Coffee.png';
import { useNavigate } from 'react-router-dom';

function App() {

  const navigate = useNavigate();

  const handleInicioSesion = () => {
    navigate("/login");
  };

  const handleRegistro = () => {
    navigate("/register");
  };



  return (
    <div className="App">
      <header className="App-header">
        <h1 className="title">CafES App</h1>
      </header>
      <main className="App-main">
        <div className="card">
          <img src={cafeImg} alt="Café Logo" className="CafeImg" />
          <div className="btn-container">
            <button className="btn btn-primary" onClick={handleInicioSesion}>Iniciar Sesión</button>
            <button className="btn btn-secondary" onClick={handleRegistro}>Registrarse</button>
          </div>
        </div>
      </main>
      <footer className="App-footer">
        <div>© {new Date().getFullYear()} IES José Zerpa - Proyecto Intermodular</div>
      </footer>
    </div>
  );
}

export default App;
